  --card-h: 124px;
  --card-radius: 10px;
  --felt: #1c6b48;
  --felt-dark: #14533a;
  --gold: #e6c15a;
  --slot-bg: rgba(255, 255, 255, 0.08);
  --slot-border: rgba(255, 255, 255, 0.35);
}

* {
  box-sizing: border-box;
}

html,
body {
