   z-index: 999;
   display: none;
   pointer-events: none;
 }

 #drag-layer .card {
   position: absolute;
   left: 0;
 }

 /* ---------- 移動アニメーション(クローンの飛行) ---------- */

 /* 飛行中に実カードを隠す(クローンが代わりに動く) */
 .card.anim-hidden {
   visibility: hidden;
 }

 #anim-layer {
   position: fixed;
   left: 0;
   top: 0;
   z-index: 1500;
   pointer-events: none;
 }

 #anim-layer .card {
   position: absolute;
   margin: 0;
   cursor: default;
 }

 /* ---------- トースト ---------- */

 #toast {
   position: fixed;
   bottom: 24px;
   left: 50%;
   transform: translateX(-50%);
   background: rgba(20, 30, 25, 0.92);
   color: #fff;
   padding: 10px 20px;
   border-radius: 10px;
   font-size: 0.9rem;
   opacity: 0;
   pointer-events: none;
   transition: opacity 0.25s ease;
   z-index: 3000;
   max-width: 90vw;
   text-align: center;
 }

 #toast.show {
   opacity: 1;
 }

 /* ---------- 勝利オーバーレイ ---------- */

 .overlay {
   position: fixed;
   inset: 0;
   background: rgba(0, 0, 0, 0.6);
   display: flex;
   align-items: center;
   justify-content: center;
   z-index: 2000;
 }

 .overlay.hidden {
   display: none;
 }

 .overlay-card {
   background: #fdfaf1;
   color: #234;
   border-radius: 16px;
   padding: 32px 44px;
   text-align: center;
   box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
   animation: pop 0.35s ease;
 }

 .overlay-card h2 {
   margin: 0 0 10px;
   color: #b8860b;
   font-size: 1.8rem;
 }

 .overlay-card button {
   margin-top: 16px;
   padding: 10px 22px;
   border: none;
   border-radius: 10px;
   background: #1c6b48;
   color: #fff;
   font-size: 1rem;
   font-weight: 600;
   cursor: pointer;
 }

 .overlay-card button:hover {
   background: #24855b;
 }

 .overlay-card button.hidden {
   display: none;
 }

 @keyframes pop {
   from {
     transform: scale(0.7);
     opacity: 0;
   }
   to {
     transform: scale(1);
     opacity: 1;
   }
 }

 /* ---------- 小さい画面 ---------- */

 @media (max-width: 800px) {
   :root {
     --card-w: 10.5vw;
     --card-h: 14.7vw;
     --card-radius: 8px;
   }

   /* 基本デザインと同じカード幅比で縮小し、801px→800px で逆に大きくなるのを防ぐ。
      コーナーは 600px 以下で中央マークが非表示になるため唯一の識別手段。
      clamp() の下限で狭幅でも読めるサイズを保証する */
   .card .corner .rank {
     font-size: clamp(0.9rem, 2.1vw, 1.1rem);
   }

   .card .corner .suit {
     font-size: clamp(0.85rem, 2vw, 1.05rem);
   }

   /* 基本サイズ(2.1rem/1.35rem)と同じカード幅比で縮小(10.5vw × 0.382 ≈ 4vw、
      × 0.245 ≈ 2.6vw)。600px 以下では非表示にする */
   .card .center-mark .center-rank {
     font-size: 4vw;
   }

   .card .center-mark .center-suit {
     font-size: 2.6vw;
   }
 }

 @media (max-width: 600px) {
   #game {
     padding-left: 6px;
     padding-right: 6px;
   }

   .top-area {
     gap: 8px;
   }

   .free-cells,
   .home-cells {
     gap: 5px;
   }

   .cascade-area {
     gap: 5px;
   }

   .card .center-mark {
     display: none;
   }
 }

 /* ---------- ヒント表示 ---------- */

 .card.hint-source {
   outline: 3px solid #6ff09a;
   outline-offset: 1px;
   box-shadow: 0 0 14px 3px rgba(111, 240, 154, 0.75);
 }

+.card.hint-target {
+  outline: 3px solid #6ff09a;
+  outline-offset: 1px;
+  box-shadow: 0 0 14px 3px rgba(111, 240, 154, 0.75);
+}
+
 .slot.hint-target {
   border-color: #6ff09a;
   box-shadow: 0 0 12px 2px rgba(111, 240, 154, 0.6);
   background: rgba(111, 240, 154, 0.18);
 }

 #game.auto-solving {
   pointer-events: none;
   opacity: 0.72;
 }

 /* ---------- 解答手順パネル ---------- */

 .solution-panel {
   position: fixed;
   inset: 0;
   background: rgba(0, 0, 0, 0.6);
   display: flex;
   align-items: center;
   justify-content: center;
   z-index: 2500;
 }

 .solution-panel.hidden {
   display: none;
 }

 .solution-card {
   background: #fdfaf1;
   color: #234;
   border-radius: 16px;
   padding: 22px 28px;
   box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
   width: min(420px, 92vw);
   max-height: 78vh;
   display: flex;
   flex-direction: column;
 }

 .solution-head {
   display: flex;
   align-items: center;
   justify-content: space-between;
 }

 .solution-head h2 {
   margin: 0;
   color: #b8860b;
   font-size: 1.3rem;
 }

 .solution-head button {
   border: none;
   background: transparent;
   color: #678;
   font-size: 1.2rem;
   cursor: pointer;
   padding: 4px 8px;
   border-radius: 8px;
 }

 .solution-head button:hover {
   background: rgba(0, 0, 0, 0.08);
 }

 #solution-summary {
   margin: 8px 0;
   font-size: 0.9rem;
   opacity: 0.8;
 }

 #solution-list {
   margin: 0;
   padding-left: 22px;
   overflow-y: auto;
   font-size: 0.92rem;
   line-height: 1.7;
   user-select: text;
   -webkit-user-select: text;
 }

