 * 空きポートの確認から HTTP サーバーの起動までに小さな競合余地が残ることは許容する。
 */
function findFreePort() {
  return new Promise((resolve, reject) => {
    const server = net.createServer();
    server.once("error", reject);
    server.listen(0, "127.0.0.1", () => {
