     await h.openGame(page, 1);
     // col0 トップから AC → 2C → 3C と連続で送れる状態
     await h.setBoard(page, {
       cascades: [[8, 4, 0], [], [], [], [], [], [], []], // 3C, 2C, AC
       freeCells: [],
       foundations: [[], [1, 5], [2, 6], [3, 7]], // ♣ 空 / ♦2 / ♥2 / ♠2
     });
     await page.click("#auto-move-btn");
     let s = await h.state(page);
