     expect(s.cascades[0]).toEqual([8, 4]);
     await page.click("#undo-btn");
     s = await h.state(page);
     expect(s.moveCount).toBe(0);
     expect(s.foundations[0]).toEqual([]);
     expect(s.cascades[0]).toEqual([8, 4, 0]);
