       const f = document.querySelectorAll("#free-cells .slot")[0].getBoundingClientRect();
       const c = document.querySelectorAll("#game .cascade")[0].querySelector(".slot").getBoundingClientRect();
       return { freeTop: f.top, cascadeTop: c.top };
     });
