     await page.addInitScript(() => {
       window.__solverDelayMs = 300;
       const NativeWorker = window.Worker;
       window.Worker = class DelayedWorker {
         constructor(url, opts) {
           this._inner = new NativeWorker(url, opts);
           this.onmessage = null;
           this.onerror = null;
           this._inner.onmessage = (e) => {
