     // clearHint は手動操作時に app 側から呼ばれる
   }

   function setAutoSolving(solving) {
     _autoSolvingFlag = solving;
     const gameEl = document.getElementById("game");
     if (gameEl) {
       gameEl.classList.toggle("auto-solving", solving);
     }
     syncControls();
   }

   /** ソルバー計算中のUI状態を制御する。
    *  mode="auto": 自動解答。ラベルに状態を表示するが、トグルは有効のまま
    *   (OFFでキャンセルできる)。テキスト幅はCSSで固定しているため位置は動かない。
    *  mode="hint": ヒント。ラベルは変更せず、トグルを無効化(自動解答開始を防ぐ)。 */
   function setSolverBusy(busy, mode) {
     if (mode === "auto") {
       solverMode = busy ? "auto" : null;
       _solverBusyFlag = busy;
       const label = document.getElementById("auto-solve-label");
       if (label) {
         if (busy) {
           if (label.dataset.prevText === undefined) {
             label.dataset.prevText = label.textContent;
           }
           label.textContent = "計算中…";
         } else {
           // 完了・キャンセル時は必ず「自動解答」に戻す
           label.textContent = "自動解答";
           delete label.dataset.prevText;
         }
       }
     } else {
       // ヒント計算中: ラベルは変えず、トグルのみ無効化
       solverMode = busy ? "hint" : null;
       _solverBusyFlag = busy;
     }
     syncControls();
   }

   /** ソルバーの現在段階を表示する(自動解答中のみ。ヒント中はラベルを変えない) */
   function setSolverStage(stage) {
     if (solverMode !== "auto") {
       return;
     }
     const label = document.getElementById("auto-solve-label");
     if (label) {
       if (stage === "safe" || stage === "safe2") {
         label.textContent = "安全探索中…";
       } else if (stage === "replay") {
         label.textContent = "自動解答中…";
       } else {
         label.textContent = "高速探索中…";
       }
     }
   }

   /** 解答手順パネルを表示する(lines は表示用文字列の配列) */
   function showSolution(lines) {
     const panel = document.getElementById("solution-panel");
     const summary = document.getElementById("solution-summary");
     const list = document.getElementById("solution-list");
     if (!panel || !list) {
       return;
     }
     if (summary) {
       summary.textContent = `全 ${lines.length} 手`;
     }
     list.innerHTML = "";
     for (const line of lines) {
       const li = document.createElement("li");
       li.textContent = line;
       list.appendChild(li);
     }
     panel.classList.remove("hidden");
   }

   function hideSolution() {
     const panel = document.getElementById("solution-panel");
     if (panel) {
       panel.classList.add("hidden");
     }
   }

   function solutionPanelEl() {
     return document.getElementById("solution-panel");
   }

   return {
     render,
     buildBoard,
     setTimerLabel,
     showToast,
     shakeEl,
     tooManyMessage,
     failFeedback,
     showWin,
     showStuck,
     hideOverlay,
     makeCardEl,
     cardElById,
     setAnimationsEnabled,
     setNextRenderAnimation,
     showHint,
     clearHint,
     setAutoSolving,
     runAfterAnimations,
     getCardRects,
     getDragCardRects,
     animateDragLayerBack,
     getDragLayer,
     buildDragLayer,
     positionDragLayer,
     hideDragLayer,
     hideCards,
     clearDropHints,
     setDropHint,
     clearDropTargets,
     setDropTarget,
     freeSlots,
     homeSlots,
     cascades,
     seedInput,
     overlayEl,
     setSolverBusy,
     setSolverStage,
     showSolution,
     hideSolution,
     solutionPanelEl,
   };
 }

